package tray

import (
	"bytes"
	_ "embed"
	"encoding/binary"
	"errors"
	"fmt"
)

// The three status tints, generated by cmd/make-tray-icons and embedded so the
// tray needs no installed files and no first-run asset extraction.
var (
	//go:embed icons/hooshix-mcp-green.ico
	iconGreen []byte

	//go:embed icons/hooshix-mcp-yellow.ico
	iconYellow []byte

	//go:embed icons/hooshix-mcp-red.ico
	iconRed []byte
)

// pngSignature is the eight-byte PNG magic number. Every frame this tray accepts
// is PNG-compressed; the container parser rejects BMP frames rather than
// pretending to support them, because CreateIconFromResourceEx does not take a
// BMP icon frame without its doubled height and mask, and a silently wrong icon
// is worse than a logged fallback.
var pngSignature = []byte("\x89PNG\r\n\x1a\n")

// iconData returns the embedded container for a readiness level.
func iconData(level readiness) []byte {
	switch level {
	case readinessGreen:
		return iconGreen
	case readinessRed:
		return iconRed
	default:
		return iconYellow
	}
}

// pickFrame extracts the frame closest to the requested pixel size. The
// notification area draws 16×16, and scaling a 256 frame down in the shell
// costs the mark its strokes, so the exact frame is preferred when present.
func pickFrame(container []byte, size int) ([]byte, error) {
	if len(container) < 6 {
		return nil, errors.New("icon container is truncated")
	}
	if kind := binary.LittleEndian.Uint16(container[2:4]); kind != 1 {
		return nil, fmt.Errorf("icon container holds type %d, not an icon", kind)
	}
	count := int(binary.LittleEndian.Uint16(container[4:6]))
	if count == 0 {
		return nil, errors.New("icon container has no frames")
	}
	if len(container) < 6+16*count {
		return nil, errors.New("icon directory is truncated")
	}
	best, bestDistance := -1, 1<<30
	for index := 0; index < count; index++ {
		width := frameWidth(container, index)
		distance := width - size
		if distance < 0 {
			distance = -distance
		}
		if distance < bestDistance {
			bestDistance, best = distance, index
		}
	}
	if best < 0 {
		return nil, errors.New("icon container has no usable frame")
	}
	entry := container[6+16*best : 6+16*(best+1)]
	offset := int(binary.LittleEndian.Uint32(entry[12:16]))
	length := int(binary.LittleEndian.Uint32(entry[8:12]))
	if offset < 6+16*count || offset+length > len(container) || length <= 0 {
		return nil, fmt.Errorf("icon frame %d points outside the container", best)
	}
	frame := container[offset : offset+length]
	if !bytes.HasPrefix(frame, pngSignature) {
		return nil, fmt.Errorf("icon frame %d is not PNG-encoded", best)
	}
	return frame, nil
}

// frameWidth decodes an ICONDIRENTRY width byte, where zero means 256.
func frameWidth(container []byte, index int) int {
	width := int(container[6+16*index])
	if width == 0 {
		return 256
	}
	return width
}
